import base64
import os
from typing import Any, Dict, List, Optional

import boto3
from botocore.exceptions import BotoCoreError, ClientError


def _load_image_bytes(image_input: Any) -> bytes:
    if image_input is None:
        raise ValueError("image_input is required")

    if isinstance(image_input, bytes):
        return image_input

    if isinstance(image_input, str):
        if image_input.startswith("data:"):
            header, _, data = image_input.partition(",")
            if ";base64" in header:
                return base64.b64decode(data)
            return data.encode("utf-8")

        if image_input.startswith("http://") or image_input.startswith("https://"):
            import urllib.request

            with urllib.request.urlopen(image_input) as resp:
                return resp.read()

        with open(image_input, "rb") as f:
            return f.read()

    if hasattr(image_input, "read"):
        data = image_input.read()
        if isinstance(data, str):
            return data.encode("utf-8")
        return data

    raise TypeError("Unsupported image_input type")


def _find_label(labels: List[Dict[str, Any]], name: str) -> Optional[Dict[str, Any]]:
    target = name.lower()
    for label in labels:
        if str(label.get("Name", "")).lower() == target:
            return label
    return None


def check_image_for_unsafe_content(image_input: Any, min_confidence: float = 70.0) -> Dict[str, Any]:
    """
    Checks an image for unsafe or policy-sensitive visual content using Amazon Rekognition.

    Returns a dictionary with:
      - unsafe: bool
      - reasons: list of matched label names / text findings
      - labels: Rekognition label payload
      - text: Rekognition text payload
    """
    image_bytes = _load_image_bytes(image_input)

    rekognition = boto3.client("rekognition")

    try:
        label_resp = rekognition.detect_labels(
            Image={"Bytes": image_bytes},
            MaxLabels=50,
            MinConfidence=min_confidence,
        )
        text_resp = rekognition.detect_text(Image={"Bytes": image_bytes})
    except (BotoCoreError, ClientError) as e:
        raise RuntimeError(f"Amazon Rekognition analysis failed: {e}") from e

    labels = label_resp.get("Labels", [])
    text_detections = text_resp.get("TextDetections", [])

    sensitive_labels = {
        "Weapon",
        "Gun",
        "Firearm",
        "Knife",
        "Blade",
        "Explosive",
        "Bomb",
        "Drug",
        "Alcohol",
        "Cigarette",
        "Smoking",
        "Nudity",
        "Sexual Activity",
        "Blood",
        "Injury",
        "Violence",
        "Fight",
        "Killing",
        "Person",
    }

    reasons: List[str] = []

    for label in labels:
        name = str(label.get("Name", ""))
        if name in sensitive_labels:
            reasons.append(name)

    for item in text_detections:
        detected_text = str(item.get("DetectedText", "")).strip()
        if not detected_text:
            continue
        lowered = detected_text.lower()
        if any(term in lowered for term in ("gun", "weapon", "bomb", "drug", "kill", "sex", "nude", "blood")):
            reasons.append(f"text:{detected_text}")

    unsafe = len(reasons) > 0

    return {
        "unsafe": unsafe,
        "reasons": sorted(set(reasons)),
        "labels": labels,
        "text": text_detections,
    }
